import cv2,numpy as np
a=cv2.imread('first_frame.png')
g=cv2.cvtColor(a,cv2.COLOR_BGR2GRAY)
# crop x110-200 y15-75, show local contrast edge using sobel and color class
# print coordinates of dark pixels per row in region
for y in range(15,76):
 xs=[]
 for x in range(105,201):
  r,gc,b=map(int,a[y,x][::-1]); lum=(r+gc+b)/3
  if lum<105: xs.append((x,lum))
 # runs
 runs=[]
 for x,l in xs:
  if not runs or x>runs[-1][-1][0]+1: runs.append([])
  runs[-1].append((x,l))
 if runs:
  print(f'y={y:02d}', ' '.join(f'{r[0][0]}-{r[-1][0]}({min(l for x,l in r):.0f})' for r in runs))
PY"

